/* From Uiverse.io by Subu19  - Tags: animation, button, hamburger, click, menu */
.__UIV_SCOPE__ .hamburger {
  height: 50px;
  width: 50px;
  transform: 0.2s;
  position: relative;
}
.__UIV_SCOPE__ .hamburger .checkbox {
  position: absolute;
  opacity: 0;
  height: 100%;
  width: 100%;
  cursor: pointer;
}
.__UIV_SCOPE__ .line {
  transition: 0.5s;
  stroke-width: 6px;
  stroke: black;
}
.__UIV_SCOPE__ .lineTop {
  stroke-dasharray: 40 40;
  stroke-dashoffset: 25;
}
.__UIV_SCOPE__ .lineBottom {
  stroke-dasharray: 40 40;
  stroke-dashoffset: 60;
}
.__UIV_SCOPE__ .lineMid {
  stroke-dasharray: 40 40;
}
.__UIV_SCOPE__ .hamburger .checkbox:checked + svg .line {
  stroke: crimson;
}
.__UIV_SCOPE__ .hamburger .checkbox:checked + svg .lineTop {
  stroke-dashoffset: 0;
  transform-origin: left;
  transform: rotateZ(45deg) translate(-7px, -5px);
}
.__UIV_SCOPE__ .hamburger .checkbox:checked + svg .lineMid {
  stroke-dashoffset: 40;
}
.__UIV_SCOPE__ .hamburger .checkbox:checked + svg .lineBottom {
  stroke-dashoffset: 0;
  transform-origin: left;
  transform: rotateZ(-45deg) translate(-5px, 5px);
}
